#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

static K_THREAD_STACK_DEFINE(k_yield_stack, STACK_SIZE);
static struct k_thread k_yield_thread;
static int thread_evidence;

/* entry point for k_yield_thread */
static void k_yield_entry_yield(void *p1, void *p2, void *p3)
{
	/* thread_evidence is used to indicate that the thread has run */
	thread_evidence = 1;
}

/**
 * @brief Test k_yield()
 *
 * This test validates that k_yield() works as expected.
 *
 * We create a thread of equal priority to the current thread, and then
 * yield to it. We then check to see that it has run.
 */
static void test_k_yield(void)
{
	/*
	 * Create a thread of equal priority, then yield to it.
	 */
	thread_evidence = 0;
	k_thread_create(&k_yield_thread, k_yield_stack, STACK_SIZE,
			k_yield_entry_yield, NULL, NULL, NULL,
			k_thread_priority_get(k_current_get()),
			0, K_NO_WAIT);

	k_yield();

	/* k_yield_thread has run and has set thread_evidence */
	zassert_equal(thread_evidence, 1, "thread did not run");
	k_thread_abort(&k_yield_thread);
}

/* entry point for k_yield_thread */
static void k_yield_entry(void *p1, void *p2, void *p3)
{
	zassert_equal(thread_evidence, 1, "thread_evidence not equal to 1");
	thread_evidence++;
}

/**
 * @brief Test timer interrupts
 *
 * This test validates that when a thread is unblocked due to a timer
 * expiration, it will preempt a thread of a lower priority.
 */
static void test_timer_interrupts(void)
{
	/*
	 * Create a thread of higher priority than the current thread,
	 * but have it sleep for one tick. The current thread will continue
	 * to run. We then busy wait for the tick to occur, and then
	 * check to see that the other thread has run.
	 */
	thread_evidence = 1;
	k_thread_create(&k_yield_thread, k_yield_stack, STACK_SIZE,
			k_yield_entry, NULL, NULL, NULL,
			K_PRIO_PREEMPT(k_thread_priority_get(k_current_get()) - 1),
			0, K_TICKS(1));

	/* wait for tick */
	k_busy_wait(USEC_PER_MSEC * 20);

	/*
	 * k_yield_thread has run and has incremented thread_evidence.
	 * We are now running again.
	 */
	zassert_equal(thread_evidence, 2, "thread did not run");
	k_thread_abort(&k_yield_thread);
}

/* A thread that does nothing but terminate */
static void nop_thread_entry(void *p1, void *p2, void *p3)
{
}

static K_THREAD_STACK_DEFINE(nop_thread_stack, STACK_SIZE);
static struct k_thread nop_thread;

/**
 * @brief test pending a thread that is not waiting
 *
 * This test pends a thread that is not waiting. The thread should
 * not be made ready to run.
 */
static void test_thread_pend_on_running(void)
{
	k_thread_create(&nop_thread, nop_thread_stack, STACK_SIZE,
			nop_thread_entry, NULL, NULL, NULL,
			k_thread_priority_get(k_current_get()) - 1,
			0, K_NO_WAIT);

	/* nop_thread will run and terminate */
	k_thread_join(&nop_thread, K_FOREVER);

	/*
	 * At this point, nop_thread is a completed thread. Resume it.
	 * This should have no effect.
	 */
	k_thread_resume(&nop_thread);

	/*
	 * Let's make sure that nop_thread is not on the ready queue.
	 * We can do this by creating a thread of the same priority,
	 * and then yielding. If nop_thread is on the ready queue,
	 * it will run.
	 */
	thread_evidence = 0;
	k_thread_create(&k_yield_thread, k_yield_stack, STACK_SIZE,
			k_yield_entry_yield, NULL, NULL, NULL,
			k_thread_priority_get(k_current_get()),
			0, K_NO_WAIT);

	k_yield();

	zassert_equal(thread_evidence, 1, "thread did not run");
	k_thread_abort(&k_yield_thread);
}

void test_main(void)
{
	ztest_test_suite(context_switch, /* descriptive name */
			 ztest_unit_test(test_k_yield),
			 ztest_unit_test(test_timer_interrupts),
			 ztest_unit_test(test_thread_pend_on_running)
			 );
	ztest_run_test_suite(context_switch);
}
